mapper.select:
-- thirdWarehouse类型 或2024-09-24 18:00:00时间点前的fba类型单据 SELECT ra.create_time as billDate, ra.id as requisitionApplicationId, ra.code as requisitionApplicationCode, ra.status as requisitionApplicationStatus, ra.type, rad.id as requisitionApplicationDetailId, fmd.id as firstMileDeliveryId, fmd.code as firstMileDeliveryCode, fmd.approve_status as deliveryApproveStatus, fmdd.id as firstMileDeliveryDetailId, fmdd.delivery_qty as deliveryQty, rad.sku_id as skuId, rad.from_warehouse_id as warehouseId, rad.from_virtual_warehouse_id as virtualWarehouseId, ra.handle_time as frozenTime, rad.virtual_frozen_qty as frozenQty, rad.approve_qty as approveQty, '' as outstockOrderId, '' as outstockOrderStatus, 0 as outstockQty, '' as outstockOrderCode, null as outstockOrderTime, '' as outstockOrderType FROM requisition_application ra INNER JOIN requisition_application_detail rad ON ra.id = rad.main_id AND rad.is_deleted = false LEFT JOIN first_mile_delivery fmd ON fmd.source_id = ra.id AND fmd.is_deleted = false AND fmd.invalid_status = false LEFT JOIN first_mile_delivery_detail fmdd ON fmdd.is_deleted = false and fmdd.source_detail_id = rad.id and fmd.id = fmdd.main_id WHERE (ra.type = 'thirdWarehouse' or (ra.type = 'fba' and '2024-09-24 18:00:00' > fmd.create_time )) AND ra.is_deleted = false AND ra.invalid_status = 'false' AND rad.from_virtual_warehouse_id != ''
and ra.create_time >= #{startDate}
UNION ALL -- fba类型且2024-09-24 18:00:00点之后的单走货件 SELECT ra.create_time as billDate, ra.id as requisitionApplicationId, ra.code as requisitionApplicationCode, ra.status as requisitionApplicationStatus, ra.type, rad.id as requisitionApplicationDetailId, fmd.id as firstMileDeliveryId, fmd.code as firstMileDeliveryCode, fmd.approve_status as deliveryApproveStatus, fmdd.id as firstMileDeliveryDetailId, fmdd.delivery_qty as deliveryQty, rad.sku_id as skuId, rad.from_warehouse_id as warehouseId, rad.from_virtual_warehouse_id as virtualWarehouseId, ra.handle_time as frozenTime, rad.virtual_frozen_qty as frozenQty, rad.approve_qty as approveQty, '' as outstockOrderId, '' as outstockOrderStatus, 0 as outstockQty, '' as outstockOrderCode, null as outstockOrderTime, '' as outstockOrderType FROM requisition_application ra INNER JOIN requisition_application_detail rad ON ra.id = rad.main_id AND rad.is_deleted = false INNER JOIN first_mile_delivery fmd ON fmd.source_id = ra.id AND fmd.is_deleted = false AND fmd.invalid_status = false INNER join ( select fmdd.id,fmdd.main_id,fmdd.delivery_qty,fsd.sku_id,fsd.fn_sku from first_mile_delivery_detail fmdd inner join fba_shipment_detail fsd on fsd.is_deleted = false and fmdd.source_detail_id = fsd.id where fmdd.is_deleted = false ) fmdd on fmd.id = fmdd.main_id and rad.sku_id = fmdd.sku_id and rad.platform_fn_sku = fmdd.fn_sku WHERE ra.type = 'fba' and fmd.create_time > '2024-09-24 18:00:00' AND ra.is_deleted = false AND ra.invalid_status = 'false' AND rad.from_virtual_warehouse_id != ''
and ra.create_time >= #{startDate}
UNION ALL -- 查询fba无发货单数据 SELECT ra.create_time as billDate, ra.id as requisitionApplicationId, ra.code as requisitionApplicationCode, ra.status as requisitionApplicationStatus, ra.type, rad.id as requisitionApplicationDetailId, '' as firstMileDeliveryId, '' as firstMileDeliveryCode, '' as deliveryApproveStatus, '' as firstMileDeliveryDetailId, 0 as deliveryQty, rad.sku_id as skuId, rad.from_warehouse_id as warehouseId, rad.from_virtual_warehouse_id as virtualWarehouseId, ra.handle_time as frozenTime, rad.virtual_frozen_qty as frozenQty, rad.approve_qty as approveQty, '' as outstockOrderId, '' as outstockOrderStatus, 0 as outstockQty, '' as outstockOrderCode, null as outstockOrderTime, '' as outstockOrderType FROM requisition_application ra INNER JOIN requisition_application_detail rad ON ra.id = rad.main_id AND rad.is_deleted = false left JOIN first_mile_delivery fmd ON fmd.source_id = ra.id AND fmd.is_deleted = false AND fmd.invalid_status = false left join ( select fmdd.id,fmdd.main_id,fmdd.delivery_qty,fsd.sku_id,fsd.fn_sku from first_mile_delivery_detail fmdd left join fba_shipment_detail fsd on fsd.is_deleted = false and fmdd.source_detail_id = fsd.id where fmdd.is_deleted = false ) fmdd on fmd.id = fmdd.main_id and rad.sku_id = fmdd.sku_id and rad.platform_fn_sku = fmdd.fn_sku WHERE ra.type = 'fba' and (fmd.create_time > '2024-09-24 18:00:00' or fmd.create_time ISNULL) AND ra.is_deleted = false AND ra.invalid_status = 'false' AND rad.from_virtual_warehouse_id != '' AND fmdd.id ISNULL
and ra.create_time >= #{startDate}

WITH qtyStatistics as ( SELECT sku_id, -- 统计每个区间的数量合计 SUM(CASE WHEN days_diff BETWEEN 0 AND 10 THEN frozen_qty ELSE 0 END) AS tenDaysCount, SUM(CASE WHEN days_diff BETWEEN 11 AND 20 THEN frozen_qty ELSE 0 END) AS twentyDaysCount, SUM(CASE WHEN days_diff BETWEEN 21 AND 30 THEN frozen_qty ELSE 0 END) AS thirtyDaysCount, SUM(CASE WHEN days_diff BETWEEN 31 AND 60 THEN frozen_qty ELSE 0 END) AS sixtyDaysCount, SUM(CASE WHEN days_diff BETWEEN 61 AND 90 THEN frozen_qty ELSE 0 END) AS ninetyDaysCount, SUM(CASE WHEN days_diff > 90 THEN frozen_qty ELSE 0 END) AS aboveNinetyDaysCount, SUM(frozen_qty) AS totalFrozenQty FROM ( SELECT sku_id, frozen_qty, DATE_PART('day', COALESCE(outstock_order_time, NOW()) - frozen_time) AS days_diff FROM first_mile_processing WHERE frozen_time IS NOT NULL ) AS subquery GROUP BY sku_id ) select 'firstMile' as type, qs.sku_id as skuId, pd.sku_no as skuNo, pd.name as productName, qs.totalFrozenQty, qs.tenDaysCount, qs.twentyDaysCount, qs.thirtyDaysCount, qs.sixtyDaysCount, qs.ninetyDaysCount, qs.aboveNinetyDaysCount from qtyStatistics qs left join product_detail pd on qs.sku_id = pd.id and pd.is_deleted = false
${params.sqlMap.default} and qs.totalFrozenQty > 0
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
qs.totalFrozenQty desc
